CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE IF NOT EXISTS schema_meta (key text PRIMARY KEY, value text NOT NULL);
CREATE TABLE IF NOT EXISTS customers (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, password_hash text NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash text PRIMARY KEY, customer_id text NOT NULL REFERENCES customers, csrf_hash text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS accounts (id text PRIMARY KEY, customer_id text NOT NULL REFERENCES customers, label text NOT NULL, last_four text NOT NULL, balance_minor bigint NOT NULL, currency text NOT NULL);
CREATE TABLE IF NOT EXISTS transactions (id text PRIMARY KEY, account_id text NOT NULL REFERENCES accounts, merchant text NOT NULL, amount_minor bigint NOT NULL, currency text NOT NULL, posted_at timestamptz NOT NULL, category text NOT NULL, status text NOT NULL DEFAULT 'posted');
CREATE TABLE IF NOT EXISTS conversations (id text PRIMARY KEY, customer_id text NOT NULL REFERENCES customers, title text NOT NULL DEFAULT 'New conversation', revision integer NOT NULL DEFAULT 0, busy_until timestamptz, run_token text, state jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS messages (id bigserial PRIMARY KEY, conversation_id text NOT NULL REFERENCES conversations, role text NOT NULL CHECK(role IN ('user','assistant')), content text NOT NULL, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS requests (conversation_id text NOT NULL REFERENCES conversations, client_id text NOT NULL, request_hash text NOT NULL, status text NOT NULL, response jsonb, PRIMARY KEY(conversation_id,client_id));
CREATE TABLE IF NOT EXISTS actions (id text PRIMARY KEY, customer_id text NOT NULL REFERENCES customers, conversation_id text NOT NULL REFERENCES conversations, kind text NOT NULL, payload jsonb NOT NULL, payload_hash text NOT NULL, version integer NOT NULL DEFAULT 1, status text NOT NULL DEFAULT 'awaiting_confirmation', expires_at timestamptz NOT NULL DEFAULT now()+interval '15 minutes', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), bank_ref text, attempts integer NOT NULL DEFAULT 0, lease_until timestamptz, last_error text, confirmation_key text);
CREATE UNIQUE INDEX IF NOT EXISTS action_confirmation_key ON actions(customer_id, confirmation_key) WHERE confirmation_key IS NOT NULL;
CREATE TABLE IF NOT EXISTS approvals (action_id text PRIMARY KEY REFERENCES actions, customer_id text NOT NULL REFERENCES customers, version integer NOT NULL, payload_hash text NOT NULL, approved_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outbox (id bigserial PRIMARY KEY, action_id text NOT NULL REFERENCES actions, published_at timestamptz, available_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS bank_disputes (id text PRIMARY KEY, customer_id text NOT NULL REFERENCES customers, transaction_id text NOT NULL REFERENCES transactions, reason text NOT NULL, idempotency_key text NOT NULL UNIQUE, request_hash text NOT NULL, status text NOT NULL DEFAULT 'received', created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS dispute_per_transaction ON bank_disputes(customer_id,transaction_id);
CREATE TABLE IF NOT EXISTS support_cases (id text PRIMARY KEY, customer_id text NOT NULL REFERENCES customers, summary text NOT NULL, status text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events (id bigserial PRIMARY KEY, actor text NOT NULL, event text NOT NULL, resource text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', trace_id text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS usage_events (id bigserial PRIMARY KEY, provider text NOT NULL, model text NOT NULL, operation text NOT NULL, input_tokens integer NOT NULL DEFAULT 0, output_tokens integer NOT NULL DEFAULT 0, outcome text NOT NULL, elapsed_ms integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS memories (id text PRIMARY KEY, kind text NOT NULL CHECK(kind='approved_policy'), title text NOT NULL, content text NOT NULL, version text NOT NULL, effective_from date NOT NULL, effective_to date, embedding_model text NOT NULL, embedding vector({embedding_dim}), approved boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS conversations_owner ON conversations(customer_id,updated_at DESC);
CREATE INDEX IF NOT EXISTS messages_conversation ON messages(conversation_id,id);
CREATE INDEX IF NOT EXISTS outbox_pending ON outbox(available_at) WHERE published_at IS NULL;
CREATE INDEX IF NOT EXISTS actions_owner ON actions(customer_id,created_at DESC);
CREATE TABLE IF NOT EXISTS rate_limits (bucket text PRIMARY KEY, count integer NOT NULL, expires_at timestamptz NOT NULL);
